import pandas as pd

def summarize_paid_orders(orders, customers):
    required_orders = {'order_id', 'customer_id', 'amount', 'status'}
    required_customers = {'customer_id', 'region'}
    if not required_orders.issubset(orders.columns) or not required_customers.issubset(customers.columns):
        raise ValueError('Thiếu cột bắt buộc')
    paid = orders.loc[orders['status'] == 'paid', ['customer_id', 'amount']].copy()
    if paid['amount'].isna().any() or (paid['amount'] < 0).any():
        raise ValueError('Amount của đơn đã thanh toán không hợp lệ')
    if customers['customer_id'].duplicated().any():
        raise ValueError('customer_id trùng trong customers')
    joined = paid.merge(customers[['customer_id', 'region']], on='customer_id', how='left', validate='many_to_one', indicator=True)
    unmatched_count = int(((joined['_merge'] == 'left_only') | joined['region'].isna()).sum())
    matched = joined.loc[(joined['_merge'] == 'both') & joined['region'].notna()]
    totals = (matched.groupby('region', as_index=False)['amount'].sum()
              .rename(columns={'amount': 'revenue'})
              .sort_values('region').reset_index(drop=True))
    return totals, unmatched_count

Tự đối chiếu: với đơn paid của khách A giá 10, khách B giá 5, khách X giá 7; customers có A thuộc Bắc, B thuộc Bắc và không có X, kết quả là Bắc có revenue 15, unmatched_count bằng 1. Đơn status khác paid không tham gia. Các bước là lọc và kiểm tra amount, kiểm tra khóa bảng khách hàng, left merge có xác nhận quan hệ khóa, đếm dòng không có region sử dụng được, rồi groupby và sắp xếp. Quyết định không gán khu vực giả giúp tránh làm sai doanh thu khu vực; đánh đổi là tổng các khu vực có thể nhỏ hơn tổng đơn paid. Rủi ro còn lại là region tuy không thiếu nhưng ghi sai chính tả vẫn tạo nhóm sai; cần quy tắc chuẩn hóa riêng nếu dữ liệu nguồn có vấn đề.
